import React,{useEffect,useState} from 'react';import {Modal} from '../../shared/preferences.tsx';
export function ProseFind({call,novelId,chapterId,prepare,applied,close,embedded=false,onBusyChange}){const [query,setQuery]=useState(''),[replacement,setReplacement]=useState(''),[scope,setScope]=useState('chapter'),[preview,setPreview]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[receipt,setReceipt]=useState(null);const reset=()=>{setPreview(null);setReceipt(null);setError('');};
 useEffect(()=>{onBusyChange?.(busy);return()=>onBusyChange?.(false);},[busy,onBusyChange]);
 const content=<div className="ps-form"><fieldset disabled={busy||!!receipt} className="structure-form"><label>范围<select value={scope} onChange={e=>{reset();setScope(e.target.value);}}><option value="chapter">本章正文</option><option value="book">全书正文</option></select></label><label>查找原文<textarea value={query} onChange={e=>{reset();setQuery(e.target.value);}}/></label><label>替换为<textarea value={replacement} onChange={e=>{reset();setReplacement(e.target.value);}}/></label></fieldset><p className="muted">按原文精确匹配，先预览再替换。替换会保存历史，关联正文依据可能需要复核。</p>{preview&&<section><strong>{preview.count} 处 · {preview.chapters.length} 章</strong>{preview.chapters.map(c=><details key={c.chapterId}><summary>{c.title} · {c.count} 处 · v{c.revision}</summary>{c.snippets.map(s=><blockquote key={s.start}>{s.before}<mark>{s.match}</mark>{s.after}<br/>替换为：{replacement||'（删除）'}</blockquote>)}{c.count>c.snippets.length&&<small>这里只展示前 20 处，替换将作用于本章全部匹配。</small>}</details>)}</section>}{error&&<p role="alert">{error}</p>}<footer className="ps-actions"><button disabled={busy||!query||!!receipt} onClick={async()=>{setBusy(true);setError('');try{await prepare();setPreview(await call('writing.prose.search',{novelId,query,replacement,...(scope==='chapter'?{chapterIds:[chapterId]}:{})}));}catch(e){setError(e.message);}finally{setBusy(false);}}}>预览匹配</button><button className="primary" disabled={busy||!preview?.count} onClick={async()=>{setBusy(true);setError('');const request=receipt||{novelId,query,replacement,...(scope==='chapter'?{chapterIds:[chapterId]}:{}),fingerprint:preview.fingerprint,confirmed:true,requestId:crypto.randomUUID()};setReceipt(request);try{await call('writing.prose.replace',request);await applied();close();}catch(e){setError(e.message);if(['CONFLICT','INVALID_INPUT','HUMAN_REQUIRED'].includes(e.code)){setReceipt(null);setPreview(null);}}finally{setBusy(false);}}}>{receipt?'重试同一次替换':'确认替换全部匹配'}</button></footer></div>;
 return embedded?content:<Modal title="查找与替换" close={()=>{if(!busy)close();}} className="prose-selection-modal">{content}</Modal>;
}
